USE [CREDITO];
SET NOCOUNT ON;

IF SCHEMA_ID(N'contabilidad') IS NULL EXEC(N'CREATE SCHEMA contabilidad');
DECLARE @muc TABLE(codigo NVARCHAR(20) NOT NULL PRIMARY KEY, nombre NVARCHAR(250) NOT NULL, naturaleza CHAR(1) NOT NULL, clase INT NULL, grupo INT NULL, nivel INT NOT NULL, nivel1 NVARCHAR(50), nivel2 NVARCHAR(50), nivel3 NVARCHAR(50));

SELECT m.codigo,m.nombre,m.naturaleza,m.clase,m.grupo,m.nivel,1
FROM @muc m
WHERE NOT EXISTS (SELECT 1 FROM contabilidad.catalogo_cuenta_muc c WHERE c.codigo_cuenta = m.codigo);

IF OBJECT_ID(N'contabilidad.catalogo_muc_detallado', N'U') IS NOT NULL
BEGIN
    SELECT m.codigo,m.nombre,m.nivel1,m.nivel2,m.nivel3,m.naturaleza,1,1
    FROM @muc m
    WHERE NOT EXISTS (SELECT 1 FROM contabilidad.catalogo_muc_detallado d WHERE d.codigo_cuenta = m.codigo);
END;

SELECT COUNT(1) AS cuentas_archivo FROM @muc;
SELECT COUNT(1) AS cuentas_catalogo FROM contabilidad.catalogo_cuenta_muc;
